import java.util.regex.*;public class TemplateFiller{public static void main(String[]x){String t="Dear {name}, order {id} ships {date}.";String[] names={"name","id"},values={"Riya","A07"};Matcher m=Pattern.compile("\\{(\\w+)\\}").matcher(t);StringBuffer b=new StringBuffer();while(m.find()){String v="[?]";for(int i=0;i<names.length;i++)if(names[i].equals(m.group(1)))v=values[i];m.appendReplacement(b,Matcher.quoteReplacement(v));}m.appendTail(b);System.out.println(b);}}
